 [STAThread] static void Main(string[] args){if(args.Contains("--dump-running-covers")){PostMessage((IntPtr)0xffff,coverDiagnosticsMessage,IntPtr.Zero,IntPtr.Zero);return;}if(args.Contains("--repair-covers")){RepairLibraryCovers();return;}if(args.Contains("--make-yuzu")){WriteYuzuArtwork(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"yuzu-cover.png"));return;}if(args.Length==2&&args[0]=="--audit-discovery"){var auditApp=new Application();var auditShelf=new Shelf(true);var auditClock=Stopwatch.StartNew();var auditGames=args[1]=="--configured"?auditShelf.DiscoverLibraries(auditShelf.LibraryFolders()):auditShelf.DiscoverGames(args[1]);File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"discovery-audit.json"),json.Serialize(new{Milliseconds=auditClock.ElapsedMilliseconds,Count=auditGames.Count,Games=auditGames}));auditShelf.Close();auditApp.Shutdown();return;}if(args.Contains("--profile-motion")){new Application().Run(new Shelf(true,true));return;}if(args.Contains("--audit-cache")){AuditLibrary();return;}if(args.Contains("--window-probe")){RunWindowProbe();return;}if(args.Contains("--make-icon")){MakeIcon(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app.ico"));return;}bool test=args.Contains("--self-test");if(!test&&!AcquireInstance())return;if(test)home=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"GameShelf-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(home);Directory.CreateDirectory(System.IO.Path.Combine(home,"covers"));using(var n=typeof(Shelf).Assembly.GetManifestResourceStream("SDL-NOTICE.txt"))if(n!=null)using(var r=new StreamReader(n))File.WriteAllText(System.IO.Path.Combine(home,"SDL-NOTICE.txt"),r.ReadToEnd());try{var app=new Application();app.DispatcherUnhandledException+=(o,e)=>{File.AppendAllText(System.IO.Path.Combine(home,"error-v2.log"),e.Exception+"\n");if(test){File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-result.txt"),e.Exception.ToString());app.Shutdown(1);}else{e.Handled=true;MessageBox.Show(e.Exception.Message,"游戏架");}};app.Run(new Shelf(test));}catch(Exception ex){File.WriteAllText(System.IO.Path.Combine(home,"error-v2.log"),ex.ToString());if(test)File.WriteAllText(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-result.txt"),ex.ToString());else MessageBox.Show(ex.Message,"游戏架");}finally{ReleaseInstance();}}
 void LoadOptions(){try{var p=System.IO.Path.Combine(home,"settings.json");if(File.Exists(p))options=json.Deserialize<Options>(File.ReadAllText(p));else {p=System.IO.Path.Combine(home,"theme.txt");if(File.Exists(p))options.Theme=File.ReadAllText(p).Trim();}if(options==null)options=new Options();if(options.Games==null)options.Games=new Dictionary<string,GameState>();}catch{options=new Options();}}
