 GameState State(Game g){string k=Hash(g.Path);if(!options.Games.ContainsKey(k))options.Games[k]=new GameState();return options.Games[k];}
 static bool IsGame(string p){return new[]{".lnk",".url",".exe"}.Contains(System.IO.Path.GetExtension(p).ToLowerInvariant());}
 static string Hash(string s){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(s))).Replace("-","").Substring(0,24);}
 static Brush B(string c){return new SolidColorBrush((Color)ColorConverter.ConvertFromString(c));}
 bool SystemDark(){try{return Convert.ToInt32(Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize","AppsUseLightTheme",1))==0;}catch{return false;}}
 void ApplyTheme(bool render){dark=theme=="深色"||(theme=="跟随系统"&&SystemDark());Resources["Fg"]=fg=B(dark?"#F2F4FF":"#23293C");Resources["Muted"]=muted=B(dark?"#A0ABC1":"#626F86");Resources["Surface"]=B(dark?"#1A2032":"#FFFFFF");Resources["Hover"]=B(dark?"#2D3651":"#E7E4FF");Resources["Line"]=B(dark?"#303A52":"#DFE4EF");Resources["Accent"]=B(Accent);Resources["AccentSoft"]=B(dark?"#323056":"#E7E0FF");Resources["Thumb"]=B(dark?"#4B5471":"#B3BCD0");Resources["Track"]=B(dark?"#151B2B":"#E9EDF5");Resources["Tip"]=B(dark?"#313B56":"#FFFFFF");bg=B(dark?"#0D1322":"#F1F4FA");Background=bg;canvas.Background=new LinearGradientBrush(dark?Color.FromRgb(22,29,48):Color.FromRgb(241,244,250),dark?Color.FromRgb(9,14,26):Color.FromRgb(231,236,247),65);if(techBackdrop!=null)techBackdrop.Opacity=dark?1:.35;foreach(var button in toolNav.Concat(tabNav))PaintIcon(button,navButton==button&&modal=="");if(render)Render();}
 IEnumerable<Game> Query(){IEnumerable<Game> q=games.Where(g=>filter=="hidden"?State(g).Hidden:!State(g).Hidden);switch(filter){case "favorite":q=q.Where(g=>State(g).Favorite);break;case "recent":q=q.Where(g=>State(g).LastPlayed>0);break;case "missing":q=q.Where(g=>!HasCover(g.Cover));break;case "unplayed":q=q.Where(g=>State(g).PlayCount==0);break;}string term=search.Text.Trim();q=q.Where(g=>g.Name.IndexOf(term,StringComparison.CurrentCultureIgnoreCase)>=0||g.OriginalName.IndexOf(term,StringComparison.CurrentCultureIgnoreCase)>=0);switch(options.Sort){case "name-desc":return q.OrderByDescending(g=>g.Name,StringComparer.CurrentCultureIgnoreCase);case "added":return q.OrderByDescending(g=>g.Added).ThenBy(g=>g.Name);case "played":return q.OrderByDescending(g=>State(g).LastPlayed).ThenBy(g=>g.Name);case "count":return q.OrderByDescending(g=>State(g).PlayCount).ThenBy(g=>g.Name);default:return q.OrderBy(g=>g.Name,StringComparer.CurrentCultureIgnoreCase);}}
