 void Highlight(bool animate){Game current=navZone=="games"&&visible.Count>selected?visible[selected]:null;if(glowingGame!=current){StopGlow();if(current!=null){Breathe(current);current.FocusMark.Opacity=1;if(current.SelectionBadge!=null)current.SelectionBadge.Visibility=Visibility.Visible;current.Lift.Y=0;current.Scale.ScaleX=current.Scale.ScaleY=1;}}if(current!=null)selectedName.Text=current.Name;}
