 void RefreshCover(Game g){if(File.Exists(g.Cover))File.Copy(g.Cover,g.Cover+".previous",true);File.Delete(g.Cover);File.Delete(g.Cover+".manual");File.Delete(g.Cover+".retry");CloseModal();Render(g.Path);UpdateCovers();}
 async void UpdateCovers(){if(busy||closing||testMode)return;busy=true;try{while(!closing){var g=games.Where(x=>!State(x).Hidden).OrderBy(x=>HasCover(x.Cover)?1:0).FirstOrDefault(x=>(!HasCover(x.Cover)||(!System.Text.RegularExpressions.Regex.IsMatch(x.OriginalName,@"[\u4e00-\u9fff]")&&!chinese.ContainsKey(x.OriginalName)&&!File.Exists(x.Cover+".title")))&&(!File.Exists(x.Cover+".retry")||File.GetLastWriteTimeUtc(x.Cover+".retry")<DateTime.UtcNow.AddHours(-12)));if(g==null)break;bool metadataOnly=HasCover(g.Cover);if(!metadataOnly)status.Text="补充缺失封面 · "+g.Name;try{bool ok=await Task.Run(()=>Fetch(g,metadataOnly));if(closing)break;if(ok&&games.Contains(g)){g.Name=DisplayName(g.OriginalName,g.Cover);Render(visible.Count>selected?visible[selected].Path:null);}else if(!ok)File.WriteAllText(g.Cover+".retry","未找到对应图片，可手动选择封面");}catch{if(!closing)File.WriteAllText(g.Cover+".retry","连接失败，稍后重试");}await Task.Delay(300);}}finally{busy=false;if(!closing)status.Text=CacheSummary(games)+" · "+folder;}}
 async void Launch(Game g){if(launching||(DateTime.Now-launched).TotalSeconds<2)return;CloseModal();launching=true;padInputArmed=false;launchWaitCancelled=false;launched=DateTime.Now;string result=null;PlayUi("launch");ShowLaunch(g);await Task.Delay(120);try{string entry=EffectiveEntry(g);if(!File.Exists(entry))throw new FileNotFoundException("游戏入口不存在，请检查目录。");var target=ResolveLaunch(new Game{Path=entry,Name=g.Name,OriginalName=g.OriginalName});using(var process=Process.Start(new ProcessStartInfo(entry==g.Path?(g.LaunchUri??entry):entry){UseShellExecute=true,Arguments=entry==g.Path?(g.Arguments??""):"",WorkingDirectory=entry==g.Path&&!string.IsNullOrWhiteSpace(g.WorkingDirectory)&&Directory.Exists(g.WorkingDirectory)?g.WorkingDirectory:System.IO.Path.GetDirectoryName(entry)})){if(process!=null&&!target.Before.Contains(process.Id))target.Tracked.Add(process.Id);}bool opened=await WaitForGameWindow(target,TimeSpan.FromSeconds(120));if(opened){State(g).LastPlayed=DateTime.UtcNow.Ticks;State(g).PlayCount++;Save();result="游戏窗口已打开 · "+g.Name;}else result=launchWaitCancelled?"已停止等待，游戏启动不受影响 · "+g.Name:"等待超时：未检测到游戏窗口 · "+g.Name;}catch(Exception ex){result="启动失败 · "+ex.Message;}finally{launching=false;if(launchLayer!=null)canvas.Children.Remove(launchLayer);launchLayer=null;if(!closing){Render(g.Path);if(result!=null)status.Text=result;}}}
 void Back(){if(launching)return;if(modal=="folder-actions"){OpenFolders();return;}PlayUi("back");if(modal=="startup-mode"||modal=="themes"||modal=="audio"||modal=="grid-size"||modal=="folders"||modal=="folder-actions"){OpenSettings();return;}if(modal!=""){CloseModal();return;}if(navZone!="games"){navZone="games";main.Focus();RefreshNavFocus();return;}if(search.Text!=""){search.Clear();main.Focus();}else if(filter!="all"){filter="all";Render();}}
